PopupListItem = class("PopupListItem")

function PopupListItem:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    self.heroId = 0;
    self.callback = nil;
    EventDelegate.Add(self.button_bg.onClick,EventDelegate.Callback(function() self:ItemClick() end));
end

function PopupListItem:ItemClick()
    if self.callback ~= nil then
        self.callback(self);
    end
end

function PopupListItem:FindComponent(transform)
    local tTransform = transform;
    self.button_bg = Util.FindChildEx(tTransform,"pic1"):GetComponent("UIButton");
    self.lab_Name = Util.FindChildEx(tTransform,"text"):GetComponent("UILabel");
end

function PopupListItem:SetItemInfo(data)
    self.id = data.id;
    self.name = data.name;
    self.lab_Name.text = self.name;
end

